sys_ux_client_script.required_translations:
[
    {
        "message": "Can't display this information"
    },
    {
        "message": "Contact your administrator for more info."
    },
    {
        "message": "Configured table is not a task table. Enter a task table."
    },
    {
        "message": "Record not found in {0}. Enter a valid record id"
    },
    {
        "message": "Record not found in the UX Header Configurations (sys_ux_header_config) table. Enter a valid Header Config ID."
    },
    {
        "message": "Record not found in the Action Configs (sys_ux_action_config) table. Enter a valid Action Config ID."
    }
]

sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
async function handler({
    api,
    event,
    helpers,
    imports
}) {
    var {
        table,
        isTableValid,
        isRecordSysIdValid,
        isHeaderConfigIdValid,
        isActionConfigIdValid,
        actionLayoutId,
        viewName
    } = api.data.validate_case_view_properties.output;
    const webComponentsUtil = imports["sn_core_components.ComponentsUtil"]();
    var headerMessage = await helpers.translate("Can't display this information"),
        endUserErrorMessage = await helpers.translate("Contact your administrator for more info."),
        tableErrorMessage = "",
        sysIdErrorMessage = "",
        headerConfigErrorMessage = "",
        actionConfigErrorMessage = "";

    if (isTableValid && isRecordSysIdValid && isHeaderConfigIdValid && isActionConfigIdValid) {
        api.setState("table", api.context.props.table ? api.context.props.table : table);
        api.setState("recordSysId", api.context.props.sysId);
        api.setState("headerConfigId", api.context.props.headerConfigurationId);
        api.setState("actionConfigId", api.context.props.actionConfigurationId);
        api.setState("actionLayoutId", actionLayoutId);
        api.setState("hideErrorComponent", true);
        api.setState("hideLoader", true);
        api.setState("tableViewForRelatedList",viewName);
    } else {
        var propertyErrors = [];
        if (!isTableValid) {
            tableErrorMessage = await helpers.translate("Configured table is not a task table. Enter a task table.");
            propertyErrors.push({
                property: "table",
                message: tableErrorMessage
            });
        } else {
            if (!isRecordSysIdValid) {
                sysIdErrorMessage = await helpers.translate("Record not found in {0}. Enter a valid record id", table);
                propertyErrors.push({
                    property: "sysId",
                    message: sysIdErrorMessage
                });
            }
            if (!isHeaderConfigIdValid) {
                headerConfigErrorMessage = await helpers.translate("Record not found in the UX Header Configurations (sys_ux_header_config) table. Enter a valid Header Config ID.");
                propertyErrors.push({
                    property: "headerConfigurationId",
                    message: headerConfigErrorMessage
                });
            }
            if (!isActionConfigIdValid) {
                actionConfigErrorMessage = await helpers.translate("Record not found in the Action Configs (sys_ux_action_config) table. Enter a valid Action Config ID.");
                propertyErrors.push({
                    property: "actionConfigurationId",
                    message: actionConfigErrorMessage
                });
            }
        }

        if (api.context.props.hideErrors)
            console.error(endUserErrorMessage);

        api.setState("errorMessageHeader", {
            label: headerMessage
        });
        api.setState("errorMessageDescription", endUserErrorMessage);
        api.setState("hideStandardTicket", true);
        api.setState("hideLoader", true);
        api.setState("hideErrorComponent", api.context.props.hideErrors);
        api.setState("table", null);

        api.emit('SN_EMBEDX_CASE_VIEW#COMPONENT_ERROR', {
            errorType: "property_error",
            errorMessage: propertyErrors
        });
    }

}
